        ON CONFLICT(project_id,plan_key) DO UPDATE SET ${merged.update.sql}`

`UPDATE tool_calls AS t SET ${mutation.update.sql}
      WHERE t.project_id = ? AND t.tool_call_id = ? AND t.session_id = ? AND ${gate.sql}
        AND ${changed.sql}
      RETURNING tool_call_id`

`INSERT OR IGNORE INTO fact_classes(project_id,table_name,record_id,session_id,class,classified_at)
      SELECT r.project_id,'${table}',r.${id},r.session_id,CASE WHEN ${legacyRowSql(table, 'r')} THEN 'legacy' ELSE 'unverified' END,${CLASSIFIED_AT_SQL}
      FROM ${table} r WHERE r.rowid>? AND r.rowid<=? AND (${legacyRowSql(table, 'r')} OR ${unverifiedRowSql('r')})`

`PRAGMA foreign_keys=ON;
   CREATE TABLE parent(project_id TEXT NOT NULL,id TEXT NOT NULL,PRIMARY KEY(project_id,id));
   CREATE TABLE required_child(project_id TEXT NOT NULL,id TEXT NOT NULL,parent_id TEXT NOT NULL,FOREIGN KEY(project_id,parent_id) REFERENCES parent(project_id,id));
   CREATE TABLE optional_child(project_id TEXT NOT NULL,id TEXT NOT NULL,parent_id TEXT,FOREIGN KEY(project_id,parent_id) REFERENCES parent(project_id,id))`
